from unittest import mock

from weather import current_temp, WeatherError


def test_current_temp_raises_weather_error_on_404(monkeypatch):
    # Mock the GET request to return a 404 status code
    def fake_get(*args, **kwargs):
        class Resp:
            status_code = 404
        return Resp()

    monkeypatch.setattr("weather.requests.get", fake_get)

    # Execute the target lines; expect WeatherError to be raised
    with pytest.raises(WeatherError, match="unknown city:"):
        current_temp("nowhere")
